import fs from 'node:fs';import path from 'node:path';import {createRequire} from 'node:module';import {hash,json} from './bounded-source-hash-20261026.mjs';
const stage='F:/VisibleMedicine/staging/20261026-quick-check-focus-native',site=stage+'/atlas',out=stage+'/browser',parent=json(json(stage+'/PREPARATION.json').parent.path);fs.mkdirSync(out);const {build}=createRequire(site+'/package.json')('esbuild');
const template=`import React,{useState} from 'react';import{createRoot}from'react-dom/client';import{StructureQuickCheck}from COMPONENT;
const first={question:'Which synthetic example is keyed?',choices:['Example A','Example B'],correctAnswer:'Example B',explanation:'Example B is the keyed example.'};
const qa=window.qa={events:[]};document.addEventListener('focusin',e=>{const t=e.target;if(t.classList.contains('structure-quick-check-feedback'))qa.events.push({kind:'feedback',text:t.textContent});if(t.matches('input[type=radio]'))qa.events.push({kind:'choice',value:t.value,checked:t.checked});});
function App(){const [props,setProps]=useState(first),[mounted,setMounted]=useState(true);qa.replace=()=>setProps({...first,explanation:'Replacement explanation.'});qa.reset=()=>setProps({...first});qa.unmount=()=>setMounted(false);qa.mount=()=>setMounted(true);qa.missing=()=>setProps({...first,correctAnswer:null});return <><h1>Structure check · synthetic focus QA</h1><input aria-label="Outside focus check"/>{mounted&&<StructureQuickCheck {...props}/>}</>};createRoot(document.getElementById('root')).render(<App/>);`;
for(const [role,root]of[['before',parent.atlas],['after',site]]){const dir=out+'/'+role;fs.mkdirSync(dir);const source=template.replace('COMPONENT',JSON.stringify(root+'/app/structure-quick-check'));const b=await build({stdin:{contents:source,resolveDir:site,sourcefile:'quick-focus-fixture.tsx',loader:'tsx'},bundle:true,write:false,outfile:'fixture.js',format:'esm',platform:'browser',jsx:'automatic',target:'es2022',metafile:true});for(const f of b.outputFiles)fs.writeFileSync(dir+'/'+path.basename(f.path),f.contents);fs.writeFileSync(dir+'/fixture-source.tsx.txt',source);const inputs=Object.keys(b.metafile.inputs).filter(p=>!p.endsWith('quick-focus-fixture.tsx')).map(p=>({path:path.resolve(site,p),sha256:hash(path.resolve(site,p))}));fs.writeFileSync(dir+'/INPUTS.json',JSON.stringify({role,inputs,component:{path:root+'/app/structure-quick-check.tsx',sha256:hash(root+'/app/structure-quick-check.tsx')},realReact:true,syntheticQuestion:true},null,2));fs.writeFileSync(dir+'/index.html','<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quick check '+role+' QA</title><link rel="stylesheet" href="/ROLE/fixture.css"><style>body{font:16px/1.45 "Segoe UI",sans-serif;margin:20px;color:#132c32;background:#f3f7f6}main{width:400px;max-width:100%}h1{font-size:21px}</style><main id="root"></main><script type="module" src="/ROLE/fixture.js"></script></html>'.replaceAll('ROLE',role));}
fs.writeFileSync(out+'/serve.mjs',`import{createServer}from'node:http';import{readFileSync}from'node:fs';const files=new Map(['before','after'].flatMap(role=>[['/'+role,role+'/index.html'],['/'+role+'/fixture.js',role+'/fixture.js'],['/'+role+'/fixture.css',role+'/fixture.css']]));const server=createServer((req,res)=>{const f=req.method==='GET'?files.get(req.url):null;if(!f){res.writeHead(404);res.end();return}res.writeHead(200,{'content-type':f.endsWith('.js')?'text/javascript':f.endsWith('.css')?'text/css':'text/html','cache-control':'no-store','content-security-policy':"default-src 'none'; script-src 'self'; style-src 'self' 'unsafe-inline'; connect-src 'none'; frame-src 'none'; form-action 'none'"});res.end(readFileSync(import.meta.dirname+'/'+f))});server.listen(0,'127.0.0.1',()=>console.log(JSON.stringify({pid:process.pid,port:server.address().port})));`);
